/* Load catalogs from the PDFs shipped in the catalogs folder. */
function pdfURL(c){
  return new URL(c.path, document.baseURI).href;
}
function download(c){
  const u=pdfURL(c); if(!u) return;
  const a=document.createElement('a'); a.href=u; a.download=c.fn;
  document.body.appendChild(a); a.click(); a.remove();
}

document.getElementById('cats').innerHTML=CATS.map((c,i)=>`
 <div class="cat">
  <button class="cover" type="button" data-v="${i}" aria-label="View ${c.t} catalog"><img src="catalogs/covers/${c.id}.png" alt="${c.t} catalog first page" loading="lazy"></button>
  <div class="cat-body"><h3>${c.t}</h3><p>${c.s}</p><p>${c.m}</p>
   <div class="cat-acts">
    <button class="mini mini-v" data-v="${i}">View</button>
    <button class="mini mini-d" data-d="${i}">Download</button>
   </div>
  </div>
 </div>`).join('');

const viewer=document.getElementById('viewer'),vpane=document.getElementById('vpane'),
      vtitle=document.getElementById('vtitle'),vdl=document.getElementById('vdl'),
      vpages=document.getElementById('vpages');
let current=null, pdfDoc=null, zoom=1, io=null, renderTok=0;

/* PDF.js renders each page to a canvas — works on every browser and every phone,
   unlike embedding a PDF in an iframe. */
function pageWidth(){
  const avail=Math.min(vpane.clientWidth-24, 980);
  return Math.max(280, avail*zoom);
}
async function openCatalog(c){
  current=c; renderTok++; const tok=renderTok;
  vtitle.textContent=c.t+' — '+c.s;
  vpane.innerHTML='<div class="vload">Opening catalog…</div>';
  viewer.classList.add('on'); document.body.classList.add('locked');
  const url=pdfURL(c); if(!url) return;
  try{
    pdfDoc=await pdfjsLib.getDocument({url:url}).promise;
    if(tok!==renderTok) return;
    layout();
  }catch(err){
    vpane.innerHTML='<div class="vload">This catalog could not be opened. '+
      'Use the Download button to save the PDF.</div>';
  }
}
function layout(){
  if(!pdfDoc) return;
  if(io) io.disconnect();
  vpane.innerHTML='';
  vpages.textContent=pdfDoc.numPages+' pages';
  const pw=pageWidth();
  vpane.style.setProperty('--pw',pw+'px');
  const holders=[];
  for(let i=1;i<=pdfDoc.numPages;i++){
    const d=document.createElement('div');
    d.className='pg'; d.dataset.p=i; d.style.aspectRatio='1 / 1.414';
    d.innerHTML='<span class="pgno">'+i+' / '+pdfDoc.numPages+'</span>';
    vpane.appendChild(d); holders.push(d);
  }
  io=new IntersectionObserver(entries=>{
    entries.forEach(en=>{ if(en.isIntersecting) renderPage(en.target); });
  },{root:vpane,rootMargin:'700px 0px'});
  holders.forEach(h=>io.observe(h));
}
async function renderPage(holder){
  if(holder.dataset.done==='1'||holder.dataset.busy==='1') return;
  holder.dataset.busy='1';
  const n=+holder.dataset.p, tok=renderTok;
  try{
    const page=await pdfDoc.getPage(n);
    if(tok!==renderTok) return;
    const pw=pageWidth();
    const base=page.getViewport({scale:1});
    const scale=(pw/base.width)*Math.min(devicePixelRatio||1,2);
    const vp=page.getViewport({scale:scale});
    const cv=document.createElement('canvas');
    cv.width=Math.floor(vp.width); cv.height=Math.floor(vp.height);
    await page.render({canvasContext:cv.getContext('2d',{alpha:false}),viewport:vp}).promise;
    if(tok!==renderTok) return;
    holder.style.aspectRatio=base.width+' / '+base.height;
    holder.insertBefore(cv,holder.firstChild);
    holder.dataset.done='1';
  }catch(e){}
  holder.dataset.busy='0';
}
function setZoom(z){
  zoom=Math.min(2.2,Math.max(.6,z));
  if(pdfDoc) layout();
}
document.getElementById('vin').onclick=()=>setZoom(zoom+.22);
document.getElementById('vout').onclick=()=>setZoom(zoom-.22);

document.getElementById('cats').addEventListener('click',e=>{
  const v=e.target.closest('[data-v]'), d=e.target.closest('[data-d]');
  if(d){ download(CATS[+d.dataset.d]); return; }
  if(v) openCatalog(CATS[+v.dataset.v]);
});
vdl.onclick=()=>{ if(current) download(current); };
function closeV(){
  renderTok++;
  viewer.classList.remove('on'); document.body.classList.remove('locked');
  if(io) io.disconnect();
  vpane.innerHTML=''; pdfDoc=null; zoom=1;
}
document.getElementById('vclose').onclick=closeV;
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&viewer.classList.contains('on'))closeV();});
let rz; addEventListener('resize',()=>{clearTimeout(rz);rz=setTimeout(()=>{if(pdfDoc&&viewer.classList.contains('on'))layout();},250);});

/* map: probe reachability first, so an offline visitor sees the address card
   instead of a browser error page inside the frame */
(function(){
  const box=document.getElementById('mapbox');
  if(!box) return;
  const q='Opp. Indo Farm House, Shri Ram Marg, Sector 25, HUDA, Panipat, Haryana 132103';
  function inject(){
    const f=document.createElement('iframe');
    f.loading='lazy'; f.title='Location of D.T. Manufactures & Traders, Panipat';
    f.referrerPolicy='no-referrer-when-downgrade';
    f.src='https://www.google.com/maps?q='+encodeURIComponent(q)+'&z=15&output=embed';
    box.appendChild(f);
  }
  if(navigator.onLine===false) return;
  let settled=false;
  const probe=new Image();
  const timer=setTimeout(()=>{settled=true;},2500);
  probe.onload=()=>{ if(!settled){settled=true;clearTimeout(timer);inject();} };
  probe.onerror=()=>{ settled=true; clearTimeout(timer); };
  probe.src='https://maps.gstatic.com/favicon.ico?'+Date.now();
})();

/* mobile menu */
const nt=document.getElementById('navtoggle'), navEl=document.querySelector('nav');
nt.addEventListener('click',()=>{
  const open=navEl.classList.toggle('open');
  nt.setAttribute('aria-expanded',open?'true':'false');
});
navEl.addEventListener('click',e=>{ if(e.target.tagName==='A'){navEl.classList.remove('open');
  nt.setAttribute('aria-expanded','false');} });

