/* ── 3D: floating machined components ── */
(function(){
  const el=document.getElementById('stage');
  if(!window.THREE||!el) return;
  const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const small=innerWidth<900;

  const scene=new THREE.Scene();
  const cam=new THREE.PerspectiveCamera(42,1,0.1,100); cam.position.set(0,0,15);
  const r=new THREE.WebGLRenderer({antialias:true,alpha:true,powerPreference:'low-power'});
  r.setPixelRatio(Math.min(devicePixelRatio,small?1.5:2));
  r.outputEncoding=THREE.sRGBEncoding;
  r.toneMapping=THREE.ACESFilmicToneMapping; r.toneMappingExposure=1.0;
  el.appendChild(r.domElement);
  el.querySelector('.stage-fallback').style.display='none';

  /* metals need something to reflect — a small procedural workshop environment */
  (function(){
    const c=document.createElement('canvas'); c.width=128; c.height=64;
    const g=c.getContext('2d');
    const grd=g.createLinearGradient(0,0,0,64);
    grd.addColorStop(0,'#e8f0f6'); grd.addColorStop(.42,'#8996a1');
    grd.addColorStop(.56,'#333d45'); grd.addColorStop(1,'#0c1013');
    g.fillStyle=grd; g.fillRect(0,0,128,64);
    g.fillStyle='rgba(239,106,30,.60)'; g.beginPath(); g.arc(26,22,15,0,6.3); g.fill();
    g.fillStyle='rgba(198,222,244,.55)'; g.beginPath(); g.arc(96,15,12,0,6.3); g.fill();
    g.fillStyle='rgba(176,141,87,.40)'; g.beginPath(); g.arc(70,44,16,0,6.3); g.fill();
    const t=new THREE.CanvasTexture(c);
    t.mapping=THREE.EquirectangularReflectionMapping;
    const pm=new THREE.PMREMGenerator(r); pm.compileEquirectangularShader();
    scene.environment=pm.fromEquirectangular(t).texture;
    pm.dispose(); t.dispose();
  })();

  scene.add(new THREE.AmbientLight(0x5d6a74,0.85));
  const key=new THREE.DirectionalLight(0xffffff,1.15); key.position.set(6,9,8); scene.add(key);
  const fill=new THREE.DirectionalLight(0x9fc4e8,0.45); fill.position.set(-8,-3,5); scene.add(fill);
  const rim=new THREE.PointLight(0xef6a1e,1.5,42); rim.position.set(-7,4,-5); scene.add(rim);
  const rim2=new THREE.PointLight(0xb08d57,0.9,36); rim2.position.set(8,-5,-4); scene.add(rim2);

  function gear(rOut,rRoot,teeth,hole,depth){
    const s=new THREE.Shape(), seg=teeth*4;
    for(let i=0;i<=seg;i++){
      const t=i/seg*Math.PI*2, ph=i%4;
      const rad=(ph===1||ph===2)?rOut:rRoot;
      const x=Math.cos(t)*rad,y=Math.sin(t)*rad;
      i?s.lineTo(x,y):s.moveTo(x,y);
    }
    const h=new THREE.Path(); h.absarc(0,0,hole,0,Math.PI*2,true); s.holes.push(h);
    return new THREE.ExtrudeGeometry(s,{depth:depth,bevelEnabled:true,
      bevelThickness:.05,bevelSize:.05,bevelSegments:1,curveSegments:14});
  }
  const steel=new THREE.MeshStandardMaterial({color:0xc4ced5,metalness:.92,roughness:.28});
  const dark =new THREE.MeshStandardMaterial({color:0x94a1aa,metalness:.88,roughness:.40});
  const brass=new THREE.MeshStandardMaterial({color:0xd0a468,metalness:.94,roughness:.29});

  const defs=[
    {g:gear(2.5,2.05,20,.75,.55),   m:steel, p:[-2.4, 1.5, 0],   s:1.15},
    {g:gear(1.65,1.35,14,.5,.42),   m:brass, p:[ 2.5, 2.5,-2.2], s:1},
    {g:gear(1.25,1.0,12,.38,.36),   m:dark,  p:[ 2.9,-1.9, .6],  s:1},
    {g:new THREE.TorusGeometry(1.5,.3,10,34), m:steel, p:[-3.0,-2.4,-1.4], s:1},
    {g:new THREE.CylinderGeometry(.42,.42,4.6,18), m:dark, p:[ .7,-3.1,-2.6], s:1},
    {g:new THREE.TorusGeometry(1.0,.34,10,26), m:brass, p:[ .2, 3.4,-3.4], s:1},
    {g:new THREE.CylinderGeometry(1.0,1.0,.85,22), m:steel, p:[-.6,-.4,-4.6], s:1}
  ];
  const parts=defs.map((d,i)=>{
    const mesh=new THREE.Mesh(d.g,d.m);
    mesh.position.set(...d.p); mesh.scale.setScalar(d.s||1);
    mesh.rotation.set(Math.random()*.9-.45,Math.random()*.9-.45,Math.random()*Math.PI);
    mesh.userData={base:d.p[1],sp:(i%2?-1:1)*(.0016+i*.0007),ph:i*1.05,amp:.16+i*.035};
    scene.add(mesh); return mesh;
  });

  let mx=0,my=0,tx=0,ty=0;
  if(!reduce&&!small) addEventListener('pointermove',e=>{
    tx=(e.clientX/innerWidth-.5)*.55; ty=(e.clientY/innerHeight-.5)*.42;
  },{passive:true});

  function size(){
    const w=el.clientWidth,h=el.clientHeight||w;
    cam.aspect=w/h; cam.updateProjectionMatrix(); r.setSize(w,h,false);
  }
  addEventListener('resize',size); size();

  let vis=true;
  new IntersectionObserver(en=>{vis=en[0].isIntersecting},{threshold:.02}).observe(el);

  const t0=performance.now();
  function loop(now){
    requestAnimationFrame(loop);
    if(!vis) return;
    const t=(now-t0)/1000;
    mx+=(tx-mx)*.045; my+=(ty-my)*.045;
    parts.forEach(p=>{
      if(!reduce){
        p.rotation.z+=p.userData.sp;
        p.rotation.x+=p.userData.sp*.35;
        p.position.y=p.userData.base+Math.sin(t*.5+p.userData.ph)*p.userData.amp;
      }
    });
    scene.rotation.y=mx; scene.rotation.x=my*.6;
    r.render(scene,cam);
  }
  requestAnimationFrame(loop);
})();

/* Inquiry delivery through the Vercel server function. */
const inquiryForm = document.getElementById('inquiry-form');
inquiryForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  if (!inquiryForm.reportValidity()) return;
  const button = inquiryForm.querySelector('[type="submit"]');
  const status = document.getElementById('inquiry-status');
  button.disabled = true;
  button.textContent = 'Sending…';
  status.textContent = 'Sending your inquiry…';
  try {
    const response = await fetch(inquiryForm.action, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(Object.fromEntries(new FormData(inquiryForm))),
    });
    const result = await response.json();
    if (!response.ok || result.ok !== true) throw new Error(result.error || 'Unable to send your inquiry.');
    status.textContent = 'Thank you! Your inquiry has been sent. We will get back to you soon.';
    inquiryForm.reset();
  } catch (error) {
    status.textContent = error instanceof SyntaxError || error instanceof TypeError
      ? 'Unable to send right now. Please try again or email purjawala@gmail.com.'
      : error.message;
  } finally {
    button.disabled = false;
    button.textContent = 'Send inquiry';
  }
});
